import { i18n } from 'src/boot/i18n';
import { convertAmountService } from 'src/services';
import { notify } from 'src/components/notifications/notify';

export default {
  methods: {
    getConversionFields() {
      return [
        'net_amount',
        'tax_amount',
        'tax_rate',
        'net_amount_2',
        'tax_amount_2',
        'tax_rate_2',
        'net_amount_3',
        'tax_amount_3',
        'tax_rate_3',
      ];
    },
    convertToUSValue(value: string) {
      return value.replace(/,/g, '.');
    },
    convertToDeValue(value: string) {
      return value.toString().replace(/\./g, ',');
    },
    normalizeLocale(locale: string) {
      return locale ? locale.toLowerCase().replace('_', '-') : locale;
    },

    convertPOValuePerLocale(locale: string, value: string) {
      const js_locale = this.normalizeLocale(locale);
      value = value ? value.replace(',', '.') : value;
      return Number(parseFloat(value)).toLocaleString(js_locale, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    },

    isValidAmount(value: string) {
      //remove spaces
      value = value.replace(/\s/g, '');
      const reg = /^[0-9.,]+$/;
      if (!reg.test(value)) {
        return false;
      }
      return true;
    },

    async convertValueAccordingToLocale(
      value: string,
      sourceLocale: string,
      destLocale: string,
    ) {
      let response;
      try {
        response = await convertAmountService.convertValueAccordingToLocale(
          value,
          sourceLocale,
          destLocale,
        );
      } catch (err) {
        notify.error(
          i18n.t('error_internal_occur'),
        );
        logError(err);
      }

      if (response) {
        return response as string;
      }
    },
  },
};
